// === CONFIG — replace every PLACEHOLDER before enabling ===
// Free key from https://livetennisapi.com/subscribe/free (100 req/day, 30/min, no card).
// Auth + base URL per their OpenAPI spec (github.com/livetennisapi/openapi) — verify against
// the live Swagger docs when you wire your key, the schema may have moved on since this draft.
const API = 'https://api.livetennisapi.com/api/public/v1';
const KEY = 'REPLACE_WITH_YOUR_LIVETENNISAPI_FREE_KEY';
const SUPABASE = 'https://YOUR-PROJECT-REF.supabase.co';
const DB_KEY = 'REPLACE_WITH_YOUR_SUPABASE_SERVICE_KEY';
const TELEGRAM_CHAT_ID = 'REPLACE_WITH_TENNIS_TELEGRAM_CHAT_ID';

const CFG = {
  ELIGIBLE_ROUNDS: ['Final', 'Semifinal'],  // criteria #1: final or semifinal only — match against the API's actual `round` values
  MIN_HISTORY_GAMES: 5,                     // criteria #2: watch 5-6 completed games before considering a signal
  MIN_SERVER_SAMPLES: 2,                    // need at least this many of the server's own service games observed
  MIN_SIGNAL_RATE: 1.0,                     // fraction of own service games that reached 40:40 required to fire ("always", per criteria #3)
  OPPONENT_HOLD_MAX_RATE: 0.5,              // only colors the reasoning text ("opponent holds serve comfortably")
  DEFAULT_ODDS_ESTIMATE: 3.20,
  GAMES_TABLE: 'tennis_4040_games_v1',      // our own reconstructed per-game deuce log (free tier has no history endpoint)
  SIGNALS_TABLE: 'tennis_4040_signals_v1'
};

const H = { Authorization: 'Bearer ' + KEY, Accept: 'application/json' };
const DH = { apikey: DB_KEY, Authorization: 'Bearer ' + DB_KEY, 'Content-Type': 'application/json', Accept: 'application/json', Prefer: 'return=representation' };

// Arrow functions so `this` (the node's execution context, for this.helpers.httpRequest)
// is captured lexically instead of depending on call-site binding.
const get = (path) => this.helpers.httpRequest({ method: 'GET', url: API + path, headers: H, json: true, timeout: 20000 });
const dbGet = (path) => this.helpers.httpRequest({ method: 'GET', url: SUPABASE + path, headers: DH, json: true, timeout: 15000 });
const dbPost = (path, body) => this.helpers.httpRequest({ method: 'POST', url: SUPABASE + path, headers: DH, body, json: true, timeout: 15000 });
const dbPatch = (path, body) => this.helpers.httpRequest({ method: 'PATCH', url: SUPABASE + path, headers: DH, body, json: true, timeout: 15000 });

// A game is treated as having reached 40:40 the moment either player hits Advantage —
// AD only exists after a 40:40 point, so seeing AD is proof deuce happened even if a
// poll lands just after the exact 40:40 instant.
const isDeuceState = (score) => (score?.p1 === '40' && score?.p2 === '40') || score?.p1 === 'AD' || score?.p2 === 'AD';

const diagnostics = {
  version: 'TENNIS_4040_HISTORY_FIRST_V1_1_DRAFT',
  matchesSeen: 0, matchesEligible: 0, snapshotErrors: 0, gamesFinalized: 0, signalsEmitted: 0,
  skipped: { notEnoughHistory: 0, notEnoughServerSamples: 0, rateBelowThreshold: 0, alreadySignaled: 0 }
};

let live = [];
try {
  const r = await get('/matches?status=live');
  live = Array.isArray(r?.data) ? r.data : Array.isArray(r) ? r : [];
} catch (e) {
  return [{ json: { isSignal: false, diagnostic: true, error: 'LIVE_FEED_UNAVAILABLE', message: String(e?.message || e), diagnostics } }];
}
diagnostics.matchesSeen = live.length;

const eligible = live.filter(m => CFG.ELIGIBLE_ROUNDS.includes(m.round));
diagnostics.matchesEligible = eligible.length;

const signals = [];
for (const match of eligible) {
  let snap;
  try {
    snap = await get('/matches/' + encodeURIComponent(match.id) + '/score');
  } catch (e) {
    diagnostics.snapshotErrors++;
    continue;
  }

  const setNum = Number(snap.set), gameNum = Number(snap.game), serverNum = Number(snap.server);
  const p1Name = match.players?.p1?.name || 'Player 1', p2Name = match.players?.p2?.name || 'Player 2';
  const serverName = serverNum === 1 ? p1Name : p2Name;
  const deuceNow = isDeuceState(snap.score);

  // --- record/refresh the CURRENT in-progress game's row (upsert-by-read, so seen_deuce only ever turns true) ---
  let currentRow = null;
  try {
    const found = await dbGet('/rest/v1/' + CFG.GAMES_TABLE + '?match_id=eq.' + encodeURIComponent(match.id) + '&set_num=eq.' + setNum + '&game_num=eq.' + gameNum + '&select=*');
    currentRow = Array.isArray(found) && found[0] ? found[0] : null;
  } catch (e) { /* treat as not-yet-seen */ }

  if (!currentRow) {
    try {
      await dbPost('/rest/v1/' + CFG.GAMES_TABLE, { match_id: match.id, set_num: setNum, game_num: gameNum, server: serverNum, server_name: serverName, seen_deuce: deuceNow, finalized: false });
    } catch (e) { /* retried next poll */ }
  } else if (deuceNow && !currentRow.seen_deuce) {
    try {
      await dbPatch('/rest/v1/' + CFG.GAMES_TABLE + '?id=eq.' + encodeURIComponent(currentRow.id), { seen_deuce: true });
    } catch (e) { /* retried next poll */ }
  }

  // --- finalize any other still-open row for this match: the live game counter moved past it, so it's over ---
  let openRows = [];
  try {
    openRows = await dbGet('/rest/v1/' + CFG.GAMES_TABLE + '?match_id=eq.' + encodeURIComponent(match.id) + '&finalized=eq.false&select=*');
    if (!Array.isArray(openRows)) openRows = [];
  } catch (e) { openRows = []; }

  for (const row of openRows) {
    if (row.set_num === setNum && row.game_num === gameNum) continue; // still in progress
    try {
      await dbPatch('/rest/v1/' + CFG.GAMES_TABLE + '?id=eq.' + encodeURIComponent(row.id), { finalized: true });
      diagnostics.gamesFinalized++;
    } catch (e) { continue; }
    // settle any pending signal that targeted this exact (match, set, game)
    try {
      await dbPatch('/rest/v1/' + CFG.SIGNALS_TABLE + '?match_id=eq.' + encodeURIComponent(match.id) + '&set_num=eq.' + row.set_num + '&game_num=eq.' + row.game_num + '&status=eq.pending',
        { status: row.seen_deuce ? 'hit' : 'miss', settled_at: new Date().toISOString() });
    } catch (e) { /* retried next poll once the row is re-finalized-checked is not re-run, so this can be retried manually if it fails */ }
  }

  // --- decide whether to fire a new signal for the CURRENT in-progress game ---
  let finalized = [];
  try {
    finalized = await dbGet('/rest/v1/' + CFG.GAMES_TABLE + '?match_id=eq.' + encodeURIComponent(match.id) + '&finalized=eq.true&order=set_num.asc,game_num.asc&select=*');
    if (!Array.isArray(finalized)) finalized = [];
  } catch (e) { finalized = []; }

  if (finalized.length < CFG.MIN_HISTORY_GAMES) { diagnostics.skipped.notEnoughHistory++; continue; }

  const ownGames = finalized.filter(r => r.server === serverNum);
  if (ownGames.length < CFG.MIN_SERVER_SAMPLES) { diagnostics.skipped.notEnoughServerSamples++; continue; }

  const hits = ownGames.filter(r => r.seen_deuce).length;
  const rate = hits / ownGames.length;
  if (rate < CFG.MIN_SIGNAL_RATE) { diagnostics.skipped.rateBelowThreshold++; continue; }

  let already = [];
  try {
    already = await dbGet('/rest/v1/' + CFG.SIGNALS_TABLE + '?match_id=eq.' + encodeURIComponent(match.id) + '&set_num=eq.' + setNum + '&game_num=eq.' + gameNum + '&select=id');
  } catch (e) { already = []; }
  if (Array.isArray(already) && already.length) { diagnostics.skipped.alreadySignaled++; continue; }

  const oppGames = finalized.filter(r => r.server !== serverNum);
  const oppHits = oppGames.filter(r => r.seen_deuce).length;
  const oppRate = oppGames.length ? oppHits / oppGames.length : null;
  const opponentName = serverNum === 1 ? p2Name : p1Name;
  const idealSignal = rate === 1 && (oppRate === null || oppRate <= CFG.OPPONENT_HOLD_MAX_RATE);

  const signal = {
    match_id: match.id,
    set_num: setNum,
    game_num: gameNum,
    tournament: match.tournament_name,
    round: match.round,
    player_a: p1Name,
    player_b: p2Name,
    server_name: serverName,
    opponent_name: opponentName,
    games_played: finalized.length,
    server_samples: ownGames.length,
    server_hit_rate: rate,
    opponent_samples: oppGames.length,
    opponent_hit_rate: oppRate,
    odds_estimate: CFG.DEFAULT_ODDS_ESTIMATE, // free tier has no live odds field; replace with a real price if your provider/book gives one
    ideal_signal: idealSignal,
    status: 'pending',
    created_at: new Date().toISOString()
  };

  try {
    await dbPost('/rest/v1/' + CFG.SIGNALS_TABLE, signal);
  } catch (e) {
    signal.persistError = String(e?.message || e); // surface it instead of silently losing the signal
  }

  diagnostics.signalsEmitted++;
  signals.push({ json: { isSignal: true, telegramChatId: TELEGRAM_CHAT_ID, ...signal, diagnostics } });
}

if (!signals.length) return [{ json: { isSignal: false, diagnostic: true, message: 'NO QUALIFYING TENNIS SIGNALS', diagnostics } }];
return signals;

const j = $json;
if (!j.isSignal) return { json: j };

const roundLabel = j.round === 'Final' ? 'Финал' : j.round === 'Semifinal' ? 'Полуфинал' : (j.round || '');
const pct = (v) => (Number(v) * 100).toFixed(1);
const hitCount = Math.round(j.server_hit_rate * j.server_samples);

const reason = [];
reason.push(j.ideal_signal ? '🔥 Идеальный сигнал!' : '⚠️ Сигнал (ниже идеального порога)');
reason.push(`В матче ${j.player_a} — ${j.player_b} (${roundLabel}) в гейме №${j.game_num} подает ${j.server_name}.`);
reason.push(`На его подаче счет 40:40 был в ${hitCount} из ${j.server_samples} геймов (${pct(j.server_hit_rate)}%).`);
if (j.opponent_hit_rate !== null && j.opponent_hit_rate <= 0.5) {
  reason.push(`При этом соперник держит подачу уверенно, поэтому ${j.server_name} вынужден вгрызаться в каждый розыгрыш на своей подаче.`);
}

const lines = [
  '🚨 СИГНАЛ НА СТАВКУ!',
  `🎾 ${j.player_a} — ${j.player_b}`,
  `🏆 Турнир: ${j.tournament}${roundLabel ? ' (' + roundLabel + ')' : ''}`,
  `📊 Сыграно геймов: ${j.games_played}`,
  `🎯 Следующий гейм: №${j.game_num} (подает ${j.server_name})`,
  '👉 Ставка: 40:40 — ДА',
  `📈 Ориентир кэфа: ~${Number(j.odds_estimate).toFixed(2)}`,
  `💬 Причина: ${reason[0]}`,
  ...reason.slice(1)
];

const text = lines.join('\n');
return { json: { ...j, text, telegram_text: text, engineVersion: 'TENNIS_4040_HISTORY_FIRST_V1_1_DRAFT' } };

// === CONFIG — replace before enabling ===
const SUPABASE = 'https://YOUR-PROJECT-REF.supabase.co';
const DB_KEY = 'REPLACE_WITH_YOUR_SUPABASE_SERVICE_KEY';
const REFERENCE_ODDS = 3.10; // reference price for this bet type, used only for the breakeven calc below — NOT the average of actual signal odds
const HISTORY_LIMIT = 5;
const SUPABASE_TABLE = 'tennis_4040_signals_v1';

const DH = { apikey: DB_KEY, Authorization: 'Bearer ' + DB_KEY, Accept: 'application/json' };
const dbGet = (path) => this.helpers.httpRequest({ method: 'GET', url: SUPABASE + path, headers: DH, json: true, timeout: 15000 });

let rows = [];
try {
  rows = await dbGet('/rest/v1/' + SUPABASE_TABLE + '?status=in.(hit,miss)&order=created_at.desc&select=*');
  if (!Array.isArray(rows)) rows = [];
} catch (e) {
  return [{ json: { error: 'STATS_QUERY_FAILED', message: String(e?.message || e) } }];
}

const total = rows.length;
const hits = rows.filter(r => r.status === 'hit').length;
const misses = total - hits;
const winratePct = total ? (hits / total) * 100 : 0;
// Breakeven% = 1 / odds * 100; Edge = winrate% - breakeven% (matches the existing bot's
// 80.0% / 32.3% @3.10 / +47.7% exactly).
const breakevenPct = (1 / REFERENCE_ODDS) * 100;
const edgePct = winratePct - breakevenPct;

const history = rows.slice(0, HISTORY_LIMIT).map(r => ({
  hit: r.status === 'hit',
  gameNumber: r.game_number,
  server: r.server,
  odds: r.odds_estimate
}));

return [{ json: { total, hits, misses, winratePct, breakevenPct, edgePct, referenceOdds: REFERENCE_ODDS, history } }];

const j = $json;
if (j.error) return { json: j };

const pct = (v) => Number(v).toFixed(1);
const lines = [
  '📊 СТАТИСТИКА СИГНАЛОВ «40:40 — ДА»',
  '━━━━━━━━━━━━━━━━━━',
  `🎯 Всего сигналов: ${j.total}`,
  `✅ Зашло (было 40:40): ${j.hits}`,
  `❌ Не зашло: ${j.misses}`,
  `📈 Винрейт: ${pct(j.winratePct)}%`,
  `⚖️ Точка окупаемости (при кэфе ~${Number(j.referenceOdds).toFixed(2)}): ${pct(j.breakevenPct)}%`,
  `⚡ Перевес над линией: ${j.edgePct >= 0 ? '+' : ''}${pct(j.edgePct)}%`,
  '━━━━━━━━━━━━━━━━━━',
  '📜 История последних сигналов:',
  ...j.history.map(h => `${h.hit ? '✅' : '❌'} Гейм ${h.gameNumber} (${h.server}): ${h.hit ? '40:40 БЫЛО' : 'без 40:40'} (кэф ${Number(h.odds).toFixed(2)})`)
];

const text = lines.join('\n');
return { json: { ...j, text, telegram_text: text } };
